static bool HandleCastDestCommand(ChatHandler* handler, char const* args)
{
    Unit* caster = handler->getSelectedUnit();
    if (!caster)
    {
        handler->SendSysMessage(LANG_SELECT_CHAR_OR_CREATURE);
        handler->SetSentErrorMessage(true);
        return false;
    }

    // number or [name] Shift-click form |color|Hspell:spell_id|h[name]|h|r or Htalent form
    uint32 spellId = handler->extractSpellIdFromLink((char*)args);
    if (!spellId || !sSpellMgr->GetSpellInfo(spellId))
    {
        handler->PSendSysMessage(LANG_COMMAND_NOSPELLFOUND);
        handler->SetSentErrorMessage(true);
        return false;
    }

    char* posX = strtok(NULL, " ");
    char* posY = strtok(NULL, " ");
    char* posZ = strtok(NULL, " ");

    if (!posX || !posY || !posZ)
        return false;

    float x, y, z;
    if (!Trinity::ParseCommandFloat(posX, x) || !Trinity::ParseCommandFloat(posY, y) ||
        !Trinity::ParseCommandFloat(posZ, z))
        return false;

    char* triggeredStr = strtok(NULL, " ");
    if (triggeredStr)
    {
        int l = strlen(triggeredStr);
        if (strncmp(triggeredStr, "triggered", l) != 0)
            return false;
    }

    bool triggered = (triggeredStr != NULL);

    caster->CastSpell(x, y, z, spellId, triggered);

    return true;
}
